int open_cypress_usb_port(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    if (!port)
        return -EINVAL;

    if (!usb_serial_port_available(port))
        return -EBUSY;

    result = usb_clear_halt(port->serial->dev, port->read_urb->pipe);
    if (result < 0) {
        dev_err(&port->dev, "Failed to clear halt on read pipe: %d\n", result);
        return result;
    }

    result = usb_clear_halt(port->serial->dev, port->write_urb->pipe);
    if (result < 0) {
        dev_err(&port->dev, "Failed to clear halt on write pipe: %d\n", result);
        return result;
    }

    tty->closing = 0;
    port->port.cflag = tty->termios.c_cflag;

    result = usb_submit_urb(port->read_urb, GFP_KERNEL);
    if (result < 0) {
        dev_err(&port->dev, "Failed to submit read urb: %d\n", result);
        port->port.dead = 1;
        return result;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int retval;

    /* Check if communication is operational */
    if (!port->port.open_count) {
        /* Clear halted states on the USB device */
        usb_clear_halt(port->serial->dev, port->read_urb->pipe);
        usb_clear_halt(port->serial->dev, port->write_urb->pipe);

        /* Reset read/write statistics */
        port->port.icount = 0;
    }

    /* Set the terminal I/O settings */
    if (tty)
        tty_set_termios(tty, &port->port);

    /* Prepare the USB interrupt transfer for reading data */
    retval = usb_submit_urb(port->read_urb, GFP_KERNEL);
    if (retval) {
        dev_err(&port->dev, "Failed to submit read urb: %d\n", retval);
        port->port.dead = 1;
        return retval;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int ret;

    if (!port->port.open_count) {
        ret = usb_serial_handle_dtr_rts(port);
        if (ret < 0)
            return ret;
    }

    usb_clear_halt(port->serial->dev, port->read_urb->pipe);
    usb_clear_halt(port->serial->dev, port->write_urb->pipe);

    tty->low_latency = 1;
    tty->no_flow_ctrl = 1;

    ret = usb_submit_urb(port->read_urb, GFP_KERNEL);
    if (ret < 0) {
        dev_err(&port->dev, "Failed to submit read urb: %d\n", ret);
        port->port.open_count = 0;
        return ret;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    if (!port->port.open_count)
        usb_serial_generic_open(tty, port);

    if (tty)
        tty->low_latency = 1;

    result = usb_submit_urb(port->interrupt_read_urb, GFP_KERNEL);
    if (result) {
        dev_err(&port->dev, "failed to submit interrupt urb: %d\n", result);
        port->port.open_count = 0;
        return result;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    if (!port)
        return -ENODEV;

    /* Clear any halted states on the USB device */
    usb_clear_halt(port->serial->dev, port->read_urb->pipe);
    usb_clear_halt(port->serial->dev, port->write_urb->pipe);

    /* Reset the read/write statistics */
    port->read_urb->status = 0;
    port->write_urb->status = 0;

    /* Set the terminal I/O settings */
    if (tty)
        tty->low_latency = 1;

    /* Prepare the USB interrupt transfer for reading data */
    result = submit_urbs(port, -1);
    if (result) {
        dev_err(&port->dev, "Failed to submit read urb: %d\n", result);
        port->serial->port->flags |= ASYNC_PORT_DEAD;
    }

    return result;
}
